<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Bars\ProviderResult;final class GroupRatingGrades{public static function summarize(ProviderResult$result):array{$subjects=[];foreach($result->details['subjects']??[]as$subject){$title=trim($subject['title']??'');if($title==='')continue;$subjects[$subject['id']??$title]=self::subject($title,$subject);}$retakes=0;$seen=[];foreach($result->items as$item){$kind=$item['kind']??'';$title=trim($item['subject_title']??'');if($title===''||!in_array($kind,['current','exam','final','assessment','control_week'],true))continue;$course=$item['course_id']??$item['subject_id']??$title;$subjects[$course]??=self::subject($title,[]);$raw=(string)($item['source_score']??$item['display_score']??$item['raw_score']??'');[$current,$previous]=self::marks($raw);if($current===null)continue;if(in_array($kind,['current','exam','final'],true)){$subjects[$course][$kind]=$kind==='current'?self::current($current):$current;continue;}$name=trim($item['assessment_title']??'');if($name==='')continue;$key=$item['assessment_id']??implode('|',[$course,$kind,$name,$item['week']??'']);if(isset($seen[$key]))continue;$seen[$key]=true;$subjects[$course]['assessments'][]=['title'=>mb_substr($name,0,200),'mark'=>$current];if($kind!=='assessment')continue;if(is_numeric($previous)&&is_numeric($current)&&(float)$previous<3&&(float)$current>=3)$retakes++;}$averaged=[];foreach($subjects as$subject){if($subject['current']!==null)$averaged[]=$subject['current'];}$subjects=array_values(array_filter($subjects,static fn(array$subject):bool=>$subject['current']!==null||$subject['final']!==null||$subject['exam']!==null||$subject['assessments']!==[]));$count=count($averaged);$average=$count?round(array_sum($averaged)/$count,2):null;$progress=self::studyProgress($subjects);$achievements=self::achievements($average,progress:$progress);if($retakes>0)$achievements[]='retake';if($retakes>=3)$achievements[]='threeRetakes';return['average'=>$average,'count'=>$co